use vstd::prelude::*;

verus! {

fn numpy_flip(m: Vec<f32>) -> (result: Vec<f32>)
    ensures
        // Output has the same length as input
        result.len() == m.len(),
        // Elements are reversed
        forall|i: int|
            0 <= i < m.len() ==> result[i] == m[(m.len() - 1 - i) as int],
{
    let n = m.len();
    let mut result: Vec<f32> = Vec::with_capacity(n);

    let mut k: usize = 0;
    while k < n
        invariant
            result.len() == k,
            k <= n,
            forall|i: int|
                0 <= i < k ==> result[i] == m[(n - 1 - i) as int],
    {
        let idx = n - 1 - k;
        result.push(m[idx]);
        k += 1;
    }

    result
}

} // verus!